function i(a){return String(a??"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/đ/g,"d").replace(/Đ/g,"D").toLowerCase().trim()}function c(a,h){if(/\d/.test(a)||/\d/.test(h)||a.length<4||Math.abs(a.length-h.length)>1)return!1;const n=Array.from({length:h.length+1},(e,o)=>o);for(let e=1;e<=a.length;e++){let o=n[0];n[0]=e;for(let t=1;t<=h.length;t++){const r=n[t];n[t]=Math.min(n[t]+1,n[t-1]+1,o+(a[e-1]===h[t-1]?0:1)),o=r}}return n[h.length]<=1}function g(a,h){const n=i(a),e=n.split(/\s+/);return i(h).split(/\s+/).every(o=>n.includes(o)||e.some(t=>c(o,t)))}const m=[["Góp ý riêng","gop y feedback phan hoi ho tro","/admin/gop-y"],["Thông báo và chiến dịch","thong bao chien dich notification campaign tri an","/admin/thong-bao"],["Sản phẩm","san pham product sku hang hoa","/admin/san-pham"],["Đơn hàng","don hang order hoa don","/admin/don-hang"],["Khách hàng","khach hang customer tai khoan","/admin/khach-hang"],["Danh mục","danh muc category nhom hang","/admin/danh-muc"],["Mã giảm giá","ma giam gia coupon voucher uu dai khuyen mai","/admin/ma-giam-gia"],["Thống kê","thong ke doanh thu bao cao dashboard","/admin/thong-ke/doanh-thu-theo-thang"],["Quản lý hình ảnh","quan ly hinh anh image gallery photo","/admin/san-pham"],["Biến thể và tồn kho","bien the ton kho size mau sac stock","/admin/chi-tiet-san-pham"]];function s(a){return i(a)?m.filter(([h,n])=>g(`${h} ${n}`,a)).map(([h,,n])=>({label:h,path:n})):[]}export{g as m,s};
